/**
 * assemble-dispute-defense-pack BullMQ worker — Sprint 21 Track C.
 *
 * Consumes `assemble-dispute-defense-pack` jobs enqueued when a Stripe
 * `charge.dispute.created` webhook fires. Gathers all available evidence
 * for a dispute (consent forms, session photos, chat history, deposit policy,
 * receipt summary) and records it in `dispute_defense_packs` via RPC.
 *
 * No PDF generation — bundle PDF is deferred to Sprint 86 (S86).
 * Stripe submission is handled by the separate dispute-evidence-submitter cron (Track D).
 *
 * Retry strategy:
 *   - Individual evidence sources that fail are logged as warnings and
 *     treated as missing (partial evidence is still submitted).
 *   - RPC writes (status update + pack record) throw on failure → BullMQ retries.
 *   - Best-effort set status='failed' on unrecoverable error.
 *
 * Job payload: { dispute_id, studio_id, charge_id }
 */
import { Worker } from 'bullmq'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { workerEnv } from '../lib/env.js'
import { RPC } from '@/lib/payments/contracts'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'assemble-dispute-defense-pack'

// ─── Payload type ─────────────────────────────────────────────────────────────

interface AssembleDisputeDefensePackPayload {
  dispute_id: string  // dp_xxx Stripe dispute ID
  studio_id: string   // UUID
  charge_id: string   // ch_xxx Stripe charge ID
}

function isAssembleDisputeDefensePackPayload(
  data: unknown
): data is AssembleDisputeDefensePackPayload {
  if (typeof data !== 'object' || data === null) return false
  const d = data as Record<string, unknown>
  return (
    typeof d['dispute_id'] === 'string' &&
    typeof d['studio_id'] === 'string' &&
    typeof d['charge_id'] === 'string'
  )
}

// ─── §S13.3 untyped Supabase query helpers ───────────────────────────────────
//
// S13+ tables are not in the generated lib/supabase/types.ts.
// Use a typed cast shim so queries still compile under strict mode without `any`.

type UntypedSelectBuilder = {
  select: (cols: string) => {
    eq: (col: string, val: string) => {
      maybeSingle: () => Promise<{ data: unknown; error: unknown }>
      order: (col: string, opts: { ascending: boolean }) => {
        limit: (n: number) => Promise<{ data: unknown; error: unknown }>
      }
      limit: (n: number) => Promise<{ data: unknown; error: unknown }>
    }
    gte: (col: string, val: string) => {
      order: (col: string, opts: { ascending: boolean }) => {
        limit: (n: number) => Promise<{ data: unknown; error: unknown }>
      }
    }
    order: (col: string, opts: { ascending: boolean }) => {
      limit: (n: number) => Promise<{ data: unknown; error: unknown }>
    }
    limit: (n: number) => Promise<{ data: unknown; error: unknown }>
  }
}

function untypedFrom(table: string): UntypedSelectBuilder {
  return (supabase.from as unknown as (t: string) => UntypedSelectBuilder)(table)
}

type UntypedRpc = (fn: string, args: Record<string, unknown>) => Promise<{ data: unknown; error: unknown }>

function untypedRpc(): UntypedRpc {
  return supabase.rpc as unknown as UntypedRpc
}

// ─── Row types for S13+ tables (narrow — only fields we read) ─────────────────

interface DisputeRow {
  id: string
  studio_id: string
  dispute_id: string
  charge_id: string
  status: string
  amount_cents: number
  currency: string
  evidence_due_by: string
  defense_pack_status: string
}

interface ChargeRow {
  id: string
  studio_id: string
  payment_intent_id: string
  charge_id: string | null
  currency: string
  amount_cents: number
  tax_amount_cents: number
  tip_amount_cents: number
  deposit_drawdown_cents: number
  booking_id: string | null
  session_id: string | null
  client_id: string | null
  project_id: string | null
  created_at: string
}

interface ConsentRow {
  id: string
  signed_pdf_url: string | null
  submitted_at: string
  form_type: string
}

interface PhotoRow {
  storage_path: string
}

interface MessageRow {
  content: string
  created_at: string
  direction: string
}

// ─── Evidence components ─────────────────────────────────────────────────────

interface EvidenceComponents {
  signedConsentUrl: string | null
  photoReleaseUrl: string | null
  sessionPhotosUrls: string[]
  chatHistorySummary: string
  depositPolicyText: string
  receiptSummary: string
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function buildStorageUrl(storagePath: string): string {
  const base = workerEnv.NEXT_PUBLIC_SUPABASE_URL
  return `${base}/storage/v1/object/public/booking-photos/${storagePath}`
}

function formatChatHistory(messages: MessageRow[]): string {
  const lines = messages.map((m) => {
    const date = m.created_at.split('T')[0] ?? m.created_at
    const dir = m.direction === 'inbound' ? 'inbound' : 'outbound'
    return `${date} [${dir}]: ${m.content}`
  })
  const full = lines.join('\n')
  // Cap at 8000 chars — Stripe evidence text field max ~9000 chars
  if (full.length <= 8000) return full
  return full.slice(0, 7997) + '...'
}

function buildReceiptSummary(charge: ChargeRow): string {
  return [
    `Payment: ${charge.currency.toUpperCase()} ${(charge.amount_cents / 100).toFixed(2)}`,
    `Tax: ${(charge.tax_amount_cents / 100).toFixed(2)}`,
    `Tip: ${(charge.tip_amount_cents / 100).toFixed(2)}`,
    `Deposit applied: ${(charge.deposit_drawdown_cents / 100).toFixed(2)}`,
    `Payment Intent: ${charge.payment_intent_id}`,
    `Date: ${new Date(charge.created_at).toISOString().split('T')[0]}`,
  ].join('\n')
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v)
}

// ─── Worker ──────────────────────────────────────────────────────────────────

export function createAssembleDisputeDefensePackWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      // ── Step 1: Validate payload ────────────────────────────────────────────
      if (!isAssembleDisputeDefensePackPayload(job.data)) {
        logger.error(
          { jobId: job.id, data: job.data },
          'assemble-dispute-defense-pack: invalid payload — skipping'
        )
        return
      }

      const payload = job.data
      const log = logger.child({
        jobId: job.id,
        disputeId: payload.dispute_id,
        studioId: payload.studio_id,
        chargeId: payload.charge_id,
      })

      log.info('assemble-dispute-defense-pack: processing')

      // ── Step 2: Fetch dispute row ───────────────────────────────────────────
      const { data: rawDispute, error: disputeErr } = await untypedFrom('stripe_disputes')
        .select('id, studio_id, dispute_id, charge_id, status, amount_cents, currency, evidence_due_by, defense_pack_status')
        .eq('dispute_id', payload.dispute_id)
        .maybeSingle()

      if (disputeErr || !rawDispute) {
        log.error({ err: disputeErr }, 'assemble-dispute-defense-pack: dispute row not found — skipping')
        return
      }

      const dispute = rawDispute as DisputeRow

      // ── Step 3: Guard — skip if already assembled ──────────────────────────
      if (
        dispute.defense_pack_status === 'ready' ||
        dispute.defense_pack_status === 'submitted'
      ) {
        log.info(
          { status: dispute.defense_pack_status },
          'assemble-dispute-defense-pack: defense pack already assembled — skipping'
        )
        return
      }

      // ── Step 4: Set status to 'assembling' ─────────────────────────────────
      const { error: assemblingErr } = await untypedRpc()(
        RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS,
        {
          p_dispute_id: payload.dispute_id,
          p_status: 'assembling',
          p_bundle_url: null,
          p_submitted_at: null,
        }
      )

      if (assemblingErr) {
        log.error({ err: assemblingErr }, 'assemble-dispute-defense-pack: failed to set status assembling — aborting')
        throw assemblingErr
      }

      // ── Step 5: Fetch charge row ────────────────────────────────────────────
      const { data: rawCharge, error: chargeErr } = await untypedFrom('stripe_charges')
        .select('id, studio_id, payment_intent_id, charge_id, currency, amount_cents, tax_amount_cents, tip_amount_cents, deposit_drawdown_cents, booking_id, session_id, client_id, project_id, created_at')
        .eq('charge_id', payload.charge_id)
        .maybeSingle()

      if (chargeErr || !rawCharge) {
        log.error({ err: chargeErr }, 'assemble-dispute-defense-pack: charge row not found — aborting')
        await setBestEffortFailed(payload.dispute_id, log)
        throw new Error(`charge row not found for charge_id=${payload.charge_id}`)
      }

      const charge = rawCharge as ChargeRow

      // ── Step 5: Gather evidence components ─────────────────────────────────

      const components: EvidenceComponents = {
        signedConsentUrl: null,
        photoReleaseUrl: null,
        sessionPhotosUrls: [],
        chatHistorySummary: '',
        depositPolicyText: 'Deposits are non-refundable per studio policy.',
        receiptSummary: buildReceiptSummary(charge),
      }

      // 5a. Consent form URL
      if (charge.booking_id) {
        try {
          const { data: consentRaw, error: consentErr } = await untypedFrom('consent_form_submissions')
            .select('id, signed_pdf_url, submitted_at, form_type')
            .eq('booking_id', charge.booking_id)
            .order('submitted_at', { ascending: false })
            .limit(5)

          if (consentErr) {
            log.warn({ err: consentErr }, 'assemble-dispute-defense-pack: failed to fetch consent forms — continuing without')
          } else if (Array.isArray(consentRaw)) {
            const rows = consentRaw as ConsentRow[]
            for (const row of rows) {
              if (row.form_type === 'photo_release' && row.signed_pdf_url && !components.photoReleaseUrl) {
                components.photoReleaseUrl = row.signed_pdf_url
              } else if (row.form_type !== 'photo_release' && row.signed_pdf_url && !components.signedConsentUrl) {
                components.signedConsentUrl = row.signed_pdf_url
              }
              if (components.signedConsentUrl && components.photoReleaseUrl) break
            }
          }
        } catch (err: unknown) {
          log.warn({ err }, 'assemble-dispute-defense-pack: exception fetching consent forms — continuing without')
        }
      }

      // 5b. Session photos (booking_photos)
      if (charge.booking_id) {
        try {
          const { data: photosRaw, error: photosErr } = await untypedFrom('booking_photos')
            .select('storage_path')
            .eq('booking_id', charge.booking_id)
            .limit(20)

          if (photosErr) {
            log.warn({ err: photosErr }, 'assemble-dispute-defense-pack: failed to fetch booking photos — continuing without')
          } else if (Array.isArray(photosRaw)) {
            const photos = photosRaw as PhotoRow[]
            components.sessionPhotosUrls = photos
              .filter((p) => typeof p.storage_path === 'string' && p.storage_path.length > 0)
              .map((p) => buildStorageUrl(p.storage_path))
          }
        } catch (err: unknown) {
          log.warn({ err }, 'assemble-dispute-defense-pack: exception fetching booking photos — continuing without')
        }
      }

      // 5c. Chat history (recent 90 days for this client)
      if (charge.client_id) {
        try {
          const since = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()
          const { data: messagesRaw, error: messagesErr } = await untypedFrom('messages')
            .select('content, created_at, direction')
            .eq('client_id', charge.client_id)
            .gte('created_at', since)
            .order('created_at', { ascending: true })
            .limit(100)

          if (messagesErr) {
            log.warn({ err: messagesErr }, 'assemble-dispute-defense-pack: failed to fetch messages — continuing without')
          } else if (Array.isArray(messagesRaw)) {
            const messages = messagesRaw as MessageRow[]
            if (messages.length > 0) {
              components.chatHistorySummary = formatChatHistory(messages)
            }
          }
        } catch (err: unknown) {
          log.warn({ err }, 'assemble-dispute-defense-pack: exception fetching messages — continuing without')
        }
      }

      // 5d. Deposit policy from studio
      try {
        const { data: studioRaw, error: studioErr } = await supabase
          .from('studios')
          .select('booking_policy, name')
          .eq('id', payload.studio_id)
          .maybeSingle()

        if (studioErr) {
          log.warn({ err: studioErr }, 'assemble-dispute-defense-pack: failed to fetch studio booking_policy — using default')
        } else if (isRecord(studioRaw)) {
          const policy = (studioRaw as { booking_policy?: string | null }).booking_policy
          if (typeof policy === 'string' && policy.length > 0) {
            components.depositPolicyText = policy
          }
        }
      } catch (err: unknown) {
        log.warn({ err }, 'assemble-dispute-defense-pack: exception fetching studio — using default deposit policy')
      }

      log.info(
        {
          hasConsent: components.signedConsentUrl !== null,
          hasPhotoRelease: components.photoReleaseUrl !== null,
          photoCount: components.sessionPhotosUrls.length,
          hasChatHistory: components.chatHistorySummary.length > 0,
        },
        'assemble-dispute-defense-pack: evidence gathered'
      )

      // ── Step 6: Record in dispute_defense_packs ────────────────────────────
      const { error: packErr } = await untypedRpc()(
        RPC.DISPUTE_DEFENSE_PACK_RECORD,
        {
          p_dispute_id: payload.dispute_id,
          p_signed_consent_url: components.signedConsentUrl,
          p_photo_release_url: components.photoReleaseUrl,
          p_session_photos_urls: components.sessionPhotosUrls,
          p_chat_history_url: null,           // stored inline as text, not as file URL
          p_deposit_policy_text: components.depositPolicyText,
          p_receipt_url: null,                // stored inline in bundle, not as file URL
          p_bundle_pdf_url: null,             // no PDF generation until S86
        }
      )

      if (packErr) {
        log.error({ err: packErr }, 'assemble-dispute-defense-pack: DISPUTE_DEFENSE_PACK_RECORD failed — will retry')
        await setBestEffortFailed(payload.dispute_id, log)
        throw packErr
      }

      // ── Step 7: Set status to 'ready' ──────────────────────────────────────
      const { error: readyErr } = await untypedRpc()(
        RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS,
        {
          p_dispute_id: payload.dispute_id,
          p_status: 'ready',
          p_bundle_url: null,         // no PDF yet (S86)
          p_submitted_at: null,
        }
      )

      if (readyErr) {
        log.error({ err: readyErr }, 'assemble-dispute-defense-pack: failed to set status ready — will retry')
        throw readyErr
      }

      log.info('assemble-dispute-defense-pack: defense pack assembled and marked ready')
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 3,
    }
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id }, 'assemble-dispute-defense-pack: job completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'assemble-dispute-defense-pack: job failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'assemble-dispute-defense-pack worker: error')
  })

  return worker
}

// ─── Best-effort status='failed' helper ──────────────────────────────────────

async function setBestEffortFailed(
  disputeId: string,
  log: ReturnType<typeof logger.child>
): Promise<void> {
  try {
    await (supabase.rpc as unknown as UntypedRpc)(
      RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS,
      {
        p_dispute_id: disputeId,
        p_status: 'failed',
        p_bundle_url: null,
        p_submitted_at: null,
      }
    )
  } catch (err: unknown) {
    // Best-effort — swallow so the original error propagates
    log.warn({ err }, 'assemble-dispute-defense-pack: best-effort status=failed update also failed')
  }
}

